const {chromium}=require('playwright');const fs=require('fs');
const paths=['/moestuin-verzorgen/','/moestuin-verzorgen/water-geven/','/moestuin-verzorgen/potgrond/','/moestuin-verzorgen/bemesten/','/moestuin-verzorgen/drainage/'];
(async()=>{fs.mkdirSync('artifacts/moestuin-verzorgen',{recursive:true});const browser=await chromium.launch({headless:true});const issues=[];const checks=[];
for(const [device,width,height] of [['mobile',375,812],['desktop',1440,900]]){const ctx=await browser.newContext({viewport:{width,height},deviceScaleFactor:1,isMobile:device==='mobile',hasTouch:device==='mobile'});for(const path of paths){const page=await ctx.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));const response=await page.goto('http://127.0.0.1:8765'+path,{waitUntil:'networkidle'});const info=await page.evaluate(()=>({title:document.title,h1:document.querySelectorAll('h1').length,canonical:document.querySelector('link[rel="canonical"]')?.href,overflow:document.documentElement.scrollWidth>window.innerWidth+2,scrollWidth:document.documentElement.scrollWidth,width:window.innerWidth,main:!!document.querySelector('main#hoofdinhoud'),skip:!!document.querySelector('a.skip-link[href="#hoofdinhoud"]'),tables:[...document.querySelectorAll('table')].map(t=>({headers:t.querySelectorAll('th[scope="col"]').length,region:!!t.closest('[role="region"][tabindex="0"]')})),brokenImages:[...document.images].filter(x=>!x.complete||x.naturalWidth===0).map(x=>x.src)}));await page.keyboard.press('Tab');const focus=await page.evaluate(()=>({href:document.activeElement?.getAttribute('href'),left:document.activeElement?getComputedStyle(document.activeElement).left:null}));const slug=path.split('/').filter(Boolean).pop();await page.screenshot({path:'artifacts/moestuin-verzorgen/'+slug+'-'+device+'.png',fullPage:true});const ok=!!response&&response.status()===200&&!info.overflow&&info.h1===1&&info.main&&info.skip&&focus.href==='#hoofdinhoud'&&focus.left!=='-9999px'&&info.brokenImages.length===0&&info.tables.every(t=>t.headers>0&&t.region)&&errors.length===0;checks.push({path,device,status:response?.status(),ok,...info,focus,errors});if(!ok)issues.push({path,device,info,focus,errors});await page.close();}await ctx.close();}await browser.close();fs.writeFileSync('artifacts/moestuin-verzorgen/results.json',JSON.stringify({count:checks.length,issues,checks},null,2));console.log(JSON.stringify({count:checks.length,issues}));if(issues.length)process.exitCode=1;})().catch(e=>{console.error(e);process.exitCode=1});